process.env.ANALYTICS_RATE_LIMIT_WINDOW_MS = '60000'
process.env.ANALYTICS_RATE_LIMIT_MAX = '1000'
process.env.ANALYTICS_APP_ALLOWED_PROPERTIES = 'app.kubus.site'

jest.mock('../src/middleware/errorHandler', () => ({
  asyncHandler: (fn) => (req, res, next) => Promise.resolve(fn(req, res, next)).catch(next),
}))

jest.mock('../src/middleware/requireWritableNode', () => ({
  requireWritableNode: () => (_req, _res, next) => next(),
}))

jest.mock('../src/services/statsService', () => ({
  trackAnalyticsEvent: jest.fn(),
}))

const express = require('express')
const request = require('supertest')
const { randomUUID } = require('crypto')

const statsService = require('../src/services/statsService')
const analyticsRouter = require('../src/routes/analytics')

function makeApp() {
  const app = express()
  app.use(express.json({ limit: '64kb' }))
  app.use('/api/analytics', analyticsRouter)
  // eslint-disable-next-line no-unused-vars
  app.use((err, _req, res, _next) => res.status(err.statusCode || 500).json({ success: false, error: err.message }))
  return app
}

const baseMetadata = {
  property: 'app.kubus.site',
  screen_name: 'MapScreen',
  screen_route: '/map',
  flow_stage: 'main',
  app_version: '0.7.2',
  build_number: 202607300,
  platform: 'web',
  env: 'prod',
}

function appEvent(eventType, metadata = {}) {
  return {
    event_id: randomUUID(),
    event_time: new Date().toISOString(),
    event_type: eventType,
    session_id: randomUUID(),
    metadata: { ...baseMetadata, ...metadata },
  }
}

function post(app, events) {
  return request(app)
    .post('/api/analytics/app')
    .set('User-Agent', 'Mozilla/5.0')
    .send({ property: 'app.kubus.site', events })
}

beforeEach(() => {
  statsService.trackAnalyticsEvent.mockReset()
  statsService.trackAnalyticsEvent.mockResolvedValue({ ok: true })
})

const ACTIVATION_EVENTS = [
  'protected_action_clicked',
  'auth_gate_viewed',
  'auth_gate_dismissed',
  'auth_method_selected',
  'registration_submitted',
  'email_verification_sent',
  'email_verification_viewed',
  'email_verified',
  'account_session_created',
  'pending_action_restored',
  'pending_action_confirmation_viewed',
  'pending_action_completed',
  'pending_action_failed',
  'first_save_completed',
  'first_follow_completed',
  'first_contribution_completed',
  'activation_prompt_viewed',
  'activation_prompt_dismissed',
  'activation_prompt_accepted',
  'exhibition_viewed',
]

test('accepts every activation funnel event type', async () => {
  const app = makeApp()
  const res = await post(app, ACTIVATION_EVENTS.map((type) => appEvent(type)))

  expect(res.status).toBe(204)
  expect(statsService.trackAnalyticsEvent).toHaveBeenCalledTimes(ACTIVATION_EVENTS.length)
  const seen = statsService.trackAnalyticsEvent.mock.calls.map(([arg]) => arg.eventType)
  expect(seen.sort()).toEqual([...ACTIVATION_EVENTS].sort())
})

test('rejects an unknown event type and stores nothing from the batch', async () => {
  const app = makeApp()
  const res = await post(app, [
    appEvent('account_session_created'),
    appEvent('totally_made_up_event'),
  ])

  expect(res.status).toBe(400)
  expect(res.body.error).toMatch(/Invalid event_type/)
  expect(statsService.trackAnalyticsEvent).not.toHaveBeenCalled()
})

test('keeps campaign attribution and hoists it onto the first-class columns', async () => {
  const app = makeApp()
  const res = await post(app, [
    appEvent('protected_action_clicked', {
      utm_source: 'meta',
      utm_medium: 'paid_social',
      utm_campaign: 'summer-art',
      utm_content: 'creative-b',
      utm_term: 'street art',
      entry_intent: 'discover',
      guest: true,
      locale: 'sl',
    }),
  ])

  expect(res.status).toBe(204)
  const [arg] = statsService.trackAnalyticsEvent.mock.calls[0]

  // Preserved in metadata...
  expect(arg.metadata.utm_source).toBe('meta')
  expect(arg.metadata.utm_campaign).toBe('summer-art')
  expect(arg.metadata.utm_content).toBe('creative-b')
  expect(arg.metadata.entry_intent).toBe('discover')
  expect(arg.metadata.guest).toBe(true)
  expect(arg.metadata.locale).toBe('sl')

  // ...and hoisted to the columns the funnel groups on.
  expect(arg.utmSource).toBe('meta')
  expect(arg.utmMedium).toBe('paid_social')
  expect(arg.utmCampaign).toBe('summer-art')
  expect(arg.utmContent).toBe('creative-b')
  expect(arg.utmTerm).toBe('street art')
})

test('stores the activation dimensions from a fixed vocabulary', async () => {
  const app = makeApp()
  const res = await post(app, [
    appEvent('pending_action_completed', {
      action_type: 'save',
      target_type: 'artwork',
      auth_method: 'google',
      continuation_status: 'completed',
      failure_stage: 'none',
      source_screen: 'map_marker',
      artwork_id: 'artwork-1',
      is_new_account: true,
    }),
  ])

  expect(res.status).toBe(204)
  const [arg] = statsService.trackAnalyticsEvent.mock.calls[0]
  expect(arg.metadata.action_type).toBe('save')
  expect(arg.metadata.target_type).toBe('artwork')
  expect(arg.metadata.auth_method).toBe('google')
  expect(arg.metadata.continuation_status).toBe('completed')
  expect(arg.metadata.failure_stage).toBe('none')
  expect(arg.metadata.source_screen).toBe('map_marker')
  expect(arg.metadata.artwork_id).toBe('artwork-1')
  expect(arg.metadata.is_new_account).toBe(true)
})

test('drops out-of-vocabulary dimension values instead of storing them', async () => {
  const app = makeApp()
  const res = await post(app, [
    appEvent('pending_action_failed', {
      action_type: 'drop_database',
      target_type: 'x'.repeat(200),
      auth_method: 'sms',
      continuation_status: 'weird',
      failure_stage: 'made_up',
      prompt_trigger: 'nope',
    }),
  ])

  expect(res.status).toBe(204)
  const [arg] = statsService.trackAnalyticsEvent.mock.calls[0]
  expect(arg.metadata.action_type).toBeUndefined()
  expect(arg.metadata.target_type).toBeUndefined()
  expect(arg.metadata.auth_method).toBeUndefined()
  expect(arg.metadata.continuation_status).toBeUndefined()
  expect(arg.metadata.failure_stage).toBeUndefined()
  expect(arg.metadata.prompt_trigger).toBeUndefined()
  // The event itself is still recorded — a bad dimension must not lose the stage.
  expect(arg.eventType).toBe('pending_action_failed')
})

test('never stores unknown metadata keys, including anything PII-shaped', async () => {
  const app = makeApp()
  const res = await post(app, [
    appEvent('account_session_created', {
      email: 'someone@example.com',
      password: 'hunter2',
      access_token: 'eyJhbGciOi',
      wallet: 'So11111111111111111111111111111111111111112',
      latitude: 46.05,
      longitude: 14.5,
      referrer: 'https://example.com/?token=secret',
    }),
  ])

  expect(res.status).toBe(204)
  const [arg] = statsService.trackAnalyticsEvent.mock.calls[0]
  for (const key of ['email', 'password', 'access_token', 'wallet', 'latitude', 'longitude', 'referrer']) {
    expect(arg.metadata[key]).toBeUndefined()
  }
})

test('clamps oversized campaign values rather than rejecting the event', async () => {
  const app = makeApp()
  const res = await post(app, [
    appEvent('map_opened', { utm_campaign: 'c'.repeat(500) }),
  ])

  expect(res.status).toBe(204)
  const [arg] = statsService.trackAnalyticsEvent.mock.calls[0]
  expect(arg.metadata.utm_campaign).toHaveLength(160)
  expect(arg.utmCampaign).toHaveLength(160)
})

test('accepts app_entry, the denominator of the direct-acquisition funnel', async () => {
  const app = makeApp()
  const res = await post(app, [
    appEvent('app_entry', { entry_route: '/register', utm_campaign: 'open_call_en' }),
  ])

  expect(res.status).toBe(204)
  const [arg] = statsService.trackAnalyticsEvent.mock.calls[0]
  expect(arg.eventType).toBe('app_entry')
  // Visitors landing straight on /register emit no guest stage at all, so this
  // is the only event that can count their entry.
  expect(arg.metadata.entry_route).toBe('/register')
  expect(arg.utmCampaign).toBe('open_call_en')
})

test('stores the entry route as a path, stripping query and fragment', async () => {
  const app = makeApp()
  const res = await post(app, [
    appEvent('app_entry', { entry_route: '/register?utm_source=meta&x=1' }),
    appEvent('app_entry', { entry_route: '/map#marker-1' }),
  ])

  expect(res.status).toBe(204)
  const routes = statsService.trackAnalyticsEvent.mock.calls.map(([arg]) => arg.metadata.entry_route)
  // An ad-hoc or sensitive query value must not reach storage through this key.
  expect(routes).toEqual(['/register', '/map'])
})

test('collapses a trailing slash so one landing surface is one breakdown row', async () => {
  const app = makeApp()
  const res = await post(app, [
    appEvent('app_entry', { entry_route: '/register/' }),
    appEvent('app_entry', { entry_route: 'register' }),
    appEvent('app_entry', { entry_route: '/' }),
  ])

  expect(res.status).toBe(204)
  const routes = statsService.trackAnalyticsEvent.mock.calls.map(([arg]) => arg.metadata.entry_route)
  // The site root keeps its single slash — it is a path, not a trailing one.
  expect(routes).toEqual(['/register', '/register', '/'])
})

test('drops arbitrary entry routes without rejecting the entry event', async () => {
  const app = makeApp()
  const res = await post(app, [
    appEvent('app_entry', { entry_route: `/${'deep/'.repeat(60)}` }),
  ])

  expect(res.status).toBe(204)
  const [arg] = statsService.trackAnalyticsEvent.mock.calls[0]
  expect(arg.metadata.entry_route).toBeUndefined()
  // Losing the entry event would leave the direct funnel without a denominator.
  expect(arg.eventType).toBe('app_entry')
})

test('drops an entry route that is empty after normalisation', async () => {
  const app = makeApp()
  const res = await post(app, [
    appEvent('app_entry', { entry_route: '?utm_source=meta' }),
  ])

  expect(res.status).toBe(204)
  const [arg] = statsService.trackAnalyticsEvent.mock.calls[0]
  expect(arg.metadata.entry_route).toBeUndefined()
  expect(arg.eventType).toBe('app_entry')
})
